package com.attempttracker;

import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CustomActivityTest
{
	@Test
	public void timedInitialDelayIsValidatedAndSeparatesDefinitions()
	{
		AttemptTrackerConfig config = timedConfig();
		CustomActivity defaultDelay = new CustomActivity(config);
		assertEquals(defaultDelay.cycle, defaultDelay.firstDelay);
		when(config.customFirstRollDelay()).thenReturn(4);
		CustomActivity earlyFirstRoll = new CustomActivity(config);
		assertTrue(earlyFirstRoll.usable());
		assertEquals(4, earlyFirstRoll.firstDelay);
		assertNotEquals(defaultDelay.signature(), earlyFirstRoll.signature());
		for (int invalid : new int[]{-1, 101, Integer.MAX_VALUE})
		{
			when(config.customFirstRollDelay()).thenReturn(invalid);
			CustomActivity rejected = new CustomActivity(config);
			assertFalse(rejected.usable());
			assertTrue(rejected.problem.contains("first-roll delay"));
		}
	}

	@Test
	public void formattingNormalizationAgreesForConfiguredPrefixesAndGameMessages()
	{
		AttemptTrackerConfig config = observedConfig();
		when(config.customSkill()).thenReturn(Skill.THIEVING);
		when(config.customSuccess()).thenReturn("<col=ffffff>You pick the Master Farmer's</col>");
		when(config.customFailure()).thenReturn("@mes_hl_red@You fail to pick the Master Farmer\u2019s");
		CustomActivity activity = new CustomActivity(config);
		assertTrue(activity.usable());
		assertEquals(Boolean.TRUE, activity.outcome("@mes_hl_gre@YOU PICK\u00a0THE Master Farmer\u2019s pocket.</col>"));
		assertEquals(Boolean.FALSE, activity.outcome("<col=ff0000>You fail to pick the Master Farmer's pocket.</col>"));
		assertEquals("you fail to pick the master farmer's pocket.",
			CustomActivity.normalize(" @MES_HL_RED@You fail to pick\u00a0the Master Farmer\u2019s pocket.</col> "));
	}

	@Test
	public void prefixesAreAnchoredAndLiteralSoQuotedMessagesCannotBecomeResults()
	{
		CustomActivity activity = new CustomActivity(observedConfig());
		assertEquals(Boolean.TRUE, activity.outcome("You catch a shark."));
		assertNull(activity.outcome("Friend: You catch a shark."));
		assertNull(activity.outcome("You receive a message: You catch a shark."));
		assertNull(activity.outcome(null));
		AttemptTrackerConfig literal = observedConfig();
		when(literal.customSuccess()).thenReturn("You catch .*");
		assertNull(new CustomActivity(literal).outcome("You catch a shark."));
	}

	@Test
	public void overlappingOutcomePrefixesRejectTheDefinitionAfterNormalization()
	{
		for (String failure : new String[]{"You catch", "You catch a shark", "@mes_hl_red@YOU\u00a0CATCH A"})
		{
			AttemptTrackerConfig config = observedConfig();
			when(config.customFailure()).thenReturn(failure);
			CustomActivity activity = new CustomActivity(config);
			assertFalse(activity.usable());
			assertTrue(activity.problem.contains("overlap"));
			assertNull(activity.outcome("You catch a shark."));
		}
	}

	@Test
	public void observedDefinitionsRequireBothOutcomesAndARealSkill()
	{
		AttemptTrackerConfig noFailure = observedConfig();
		when(noFailure.customFailure()).thenReturn("<col=ff0000></col>");
		assertFalse(new CustomActivity(noFailure).usable());
		assertTrue(new CustomActivity(noFailure).problem.contains("failure prefixes"));
		for (Skill skill : new Skill[]{Skill.OVERALL, null})
		{
			AttemptTrackerConfig config = observedConfig();
			when(config.customSkill()).thenReturn(skill);
			assertFalse(new CustomActivity(config).usable());
		}
		AttemptTrackerConfig disabled = observedConfig();
		when(disabled.customEnabled()).thenReturn(false);
		when(disabled.customSuccess()).thenReturn("");
		assertFalse(new CustomActivity(disabled).usable());
		assertEquals("", new CustomActivity(disabled).problem);
	}

	@Test
	public void timedDefinitionsRejectInvalidAnimationListsAndCycles()
	{
		for (String animations : new String[]{"", "622,nope", "-1", "2147483648", "622,", "622,,623"})
		{
			AttemptTrackerConfig config = timedConfig();
			when(config.customAnimations()).thenReturn(animations);
			assertFalse(animations, new CustomActivity(config).usable());
			assertTrue(new CustomActivity(config).problem.contains("animation"));
		}
		for (int cycle : new int[]{0, -1, 101, Integer.MAX_VALUE})
		{
			AttemptTrackerConfig config = timedConfig();
			when(config.customCycle()).thenReturn(cycle);
			assertFalse(new CustomActivity(config).usable());
			assertTrue(new CustomActivity(config).problem.contains("cycle"));
		}
		assertTrue(new CustomActivity(timedConfig()).usable());
	}

	@Test
	public void timedDefinitionsRequireLiteralAnchoredStartPrefixes()
	{
		AttemptTrackerConfig config = timedConfig();
		when(config.customStart()).thenReturn("<col=ffffff>You start harpooning</col>\n@mes_hl_gre@YOU START\u00a0HARPOONING\nYou cast out your line.");
		CustomActivity activity = new CustomActivity(config);
		assertTrue(activity.usable());
		assertEquals(2, activity.starts.size());
		assertTrue(activity.matchesStart("@mes_hl_gre@YOU START\u00a0HARPOONING fish.</col>"));
		assertTrue(activity.matchesStart("You cast out your line."));
		assertFalse(activity.matchesStart("Friend: You start harpooning fish."));
		assertFalse(activity.matchesStart("You catch a shark!"));
		assertFalse(activity.matchesStart(null));

		when(config.customStart()).thenReturn("<col=ffffff></col>");
		CustomActivity noStart = new CustomActivity(config);
		assertFalse(noStart.usable());
		assertTrue(noStart.problem.contains("start-message prefix"));

		when(config.customStart()).thenReturn("You start .*");
		assertFalse(new CustomActivity(config).matchesStart("You start harpooning fish."));
	}

	@Test
	public void observedDefinitionsDoNotNeedOrMatchStartMessages()
	{
		AttemptTrackerConfig config = observedConfig();
		when(config.customStart()).thenReturn("You start harpooning");
		CustomActivity activity = new CustomActivity(config);
		assertTrue(activity.usable());
		assertFalse(activity.matchesStart("You start harpooning fish."));
	}

	@Test
	public void timedStartPrefixesCannotOverlapEitherOutcome()
	{
		for (String start : new String[]{"You catch", "You catch a shark", "<col=ffffff>YOU</col>", "You fail to catch a shark"})
		{
			AttemptTrackerConfig config = timedConfig();
			when(config.customStart()).thenReturn(start);
			when(config.customFailure()).thenReturn("You fail to catch");
			CustomActivity activity = new CustomActivity(config);
			assertFalse(activity.usable());
			assertTrue(activity.problem.contains("start and outcome prefixes overlap"));
		}
	}

	@Test
	public void changingStartDefinitionChangesItsSetupSignature()
	{
		AttemptTrackerConfig config = timedConfig();
		String initial = new CustomActivity(config).signature();
		when(config.customStart()).thenReturn("You cast out your line.");
		assertNotEquals(initial, new CustomActivity(config).signature());
		when(config.customStart()).thenReturn("  <col=ffffff>YOU START HARPOONING</col>  ");
		assertEquals(initial, new CustomActivity(config).signature());
	}

	private static AttemptTrackerConfig observedConfig()
	{
		AttemptTrackerConfig config = mock(AttemptTrackerConfig.class);
		when(config.customEnabled()).thenReturn(true);
		when(config.customName()).thenReturn("Custom fishing");
		when(config.customSkill()).thenReturn(Skill.FISHING);
		when(config.customMode()).thenReturn(AttemptTrackerConfig.CustomMode.OBSERVED);
		when(config.customCycle()).thenReturn(5);
		when(config.customSuccess()).thenReturn("You catch a");
		when(config.customFailure()).thenReturn("You fail to catch");
		return config;
	}

	private static AttemptTrackerConfig timedConfig()
	{
		AttemptTrackerConfig config = observedConfig();
		when(config.customMode()).thenReturn(AttemptTrackerConfig.CustomMode.TIMED);
		when(config.customAnimations()).thenReturn("622, 623");
		when(config.customStart()).thenReturn("You start harpooning");
		when(config.customFailure()).thenReturn("");
		return config;
	}
}

package com.attempttracker.store;

import com.attempttracker.core.AttemptSession;
import com.attempttracker.core.TrackingMethod;
import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import net.runelite.client.util.Filepath;
import static com.attempttracker.FilepathTestSupport.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Stream;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

public class SessionStoreTest
{
	@Rule
	public TemporaryFolder temporary = new TemporaryFolder();

	@Test
	public void legacyCsvExportAlsoAcceptsAFileScopedSelection() throws IOException
	{
		Filepath directory = Filepath.Unchecked.getRooted(temporary.newFolder().toPath());
		Filepath selected = directory.join("legacy.csv").rooted();
		new SessionStore(directory, new Gson()).exportCsv(Collections.singletonList(session("one", "Fishing", "", 9, 1)), selected);
		assertTrue(readString(selected).contains(",10,9,1,0.9,"));
	}

	@Test
	public void roundTripPreservesAllSessionFieldsAndLeavesNoTemporaryFiles() throws IOException
	{
		Filepath directory = Filepath.Unchecked.getRooted(temporary.newFolder().toPath());
		SessionStore store = new SessionStore(directory, new Gson());
		AttemptSession original = session("one", "Shark fishing", "Crystal harpoon; 3 lures", 950, 50);
		store.save(Collections.singletonList(original));
		AttemptSession restored = store.load().get(0);
		assertEquals(original.getId(), restored.getId());
		assertEquals(original.getActivity(), restored.getActivity());
		assertEquals(original.getSetup(), restored.getSetup());
		assertEquals(original.getMethod(), restored.getMethod());
		assertEquals(original.getStartedAt(), restored.getStartedAt());
		assertEquals(original.getUpdatedAt(), restored.getUpdatedAt());
		assertEquals(1000, restored.getAttempts());
		assertEquals(950, restored.getSuccesses());
		assertEquals(50, restored.getFailures());
		assertEquals(2, restored.getExcludedWindows());
		assertEquals(5, restored.getCycleTicks());
		assertEquals("", store.getLastLoadWarning());
		store.save(Collections.singletonList(session("two", "Cooking", "", 1, 2)));
		assertEquals("two", store.load().get(0).getId());
		try (Stream<Filepath> files = directory.walk(1).filter(path -> !path.equals(directory)))
		{
			assertEquals(1, files.count());
		}
	}

	@Test
	public void corruptOrUnsupportedHistoryDoesNotCrashOrChangeSource() throws IOException
	{
		Filepath directory = Filepath.Unchecked.getRooted(temporary.newFolder().toPath());
		SessionStore store = new SessionStore(directory, new Gson());
		Filepath source = directory.join("sessions.json");
		for (String invalid : Arrays.asList("{broken", "null", "[]", "{\"version\":99,\"sessions\":[]}"))
		{
			source.write(invalid.getBytes(StandardCharsets.UTF_8));
			assertTrue(store.load().isEmpty());
			assertFalse(store.getLastLoadWarning().isEmpty());
			assertEquals(invalid, new String(readBytes(source), StandardCharsets.UTF_8));
		}
	}

	@Test
	public void oversizedFilesAreRejectedAndSessionHistoryIsBounded() throws IOException
	{
		Filepath directory = Filepath.Unchecked.getRooted(temporary.newFolder().toPath());
		SessionStore store = new SessionStore(directory, new Gson());
		directory.join("sessions.json").write( new byte[2 * 1024 * 1024 + 1]);
		assertTrue(store.load().isEmpty());
		assertTrue(store.getLastLoadWarning().contains("size limit"));
		List<AttemptSession> sessions = new ArrayList<>();
		for (int i = 0; i < 250; i++)
		{
			sessions.add(session("id-" + i, "Fishing", "", 1, 0));
		}
		store.save(sessions);
		assertEquals(200, store.load().size());
		assertEquals("id-0", store.load().get(0).getId());
	}

	@Test
	public void invalidEntriesAreSkippedWithoutDiscardingValidEntries() throws IOException
	{
		Filepath directory = Filepath.Unchecked.getRooted(temporary.newFolder().toPath());
		SessionStore store = new SessionStore(directory, new Gson());
		String valid = new Gson().toJson(session("ok", "Fishing", "", 1, 0));
		directory.join("sessions.json").write(
			("{\"version\":1,\"sessions\":[null,42,{\"successes\":\"bad\"}," + valid + "]}").getBytes(StandardCharsets.UTF_8));
		assertEquals(1, store.load().size());
		assertEquals("ok", store.load().get(0).getId());
		assertFalse(store.getLastLoadWarning().isEmpty());
	}

	@Test
	public void unreadableHistoryIsBackedUpBeforeTheFirstReplacement() throws IOException
	{
		Filepath directory = Filepath.Unchecked.getRooted(temporary.newFolder().toPath());
		Filepath source = directory.join("sessions.json");
		String corrupt = "{recover this history manually";
		source.write(corrupt.getBytes(StandardCharsets.UTF_8));
		SessionStore store = new SessionStore(directory, new Gson());
		assertTrue(store.load().isEmpty());
		store.save(Collections.singletonList(session("new", "Fishing", "", 1, 0)));
		List<Filepath> backups = new ArrayList<>();
		try (Stream<Filepath> files = directory.walk(1).filter(path -> !path.equals(directory)))
		{
			files.filter(path -> path.getFileName().startsWith("sessions.unreadable-")).forEach(backups::add);
		}
		assertEquals(1, backups.size());
		assertEquals(corrupt, new String(readBytes(backups.get(0)), StandardCharsets.UTF_8));
		assertEquals("new", store.load().get(0).getId());
		store.save(Collections.singletonList(session("newer", "Fishing", "", 2, 0)));
		try (Stream<Filepath> files = directory.walk(1).filter(path -> !path.equals(directory)))
		{
			assertEquals(2, files.count());
		}
	}

	@Test
	public void successesOnlyCsvLeavesUnknownCountsAndRatesBlank() throws IOException
	{
		Filepath directory = Filepath.Unchecked.getRooted(temporary.newFolder().toPath());
		Filepath exported = directory.join("successes.csv");
		AttemptSession catches = new AttemptSession("only", "Fishing", "", TrackingMethod.SUCCESS_ONLY,
			1_790_900_000_000L, 1_790_900_000_000L, 42, 0, 0, 0);
		new SessionStore(directory, new Gson()).exportCsv(Collections.singletonList(catches), exported);
		String row = readLines(exported).get(1);
		String[] columns = row.split(",", -1);
		assertEquals(14, columns.length);
		assertEquals("", columns[6]);
		assertEquals("42", columns[7]);
		for (int i = 8; i <= 11; i++)
		{
			assertEquals("", columns[i]);
		}
	}

	@Test
	public void csvEscapesQuotesNewlinesAndNeutralizesSpreadsheetFormulas() throws IOException
	{
		assertEquals("\"'  =SUM(1,2)\"", SessionStore.csvText("  =SUM(1,2)"));
		assertEquals("\"'+cmd\"", SessionStore.csvText("+cmd"));
		assertEquals("\"'-cmd\"", SessionStore.csvText("-cmd"));
		assertEquals("\"'@SUM(1)\"", SessionStore.csvText("@SUM(1)"));
		assertEquals("\"'\tvalue\"", SessionStore.csvText("\tvalue"));
		assertEquals("\"line\n\"\"quoted\"\"\"", SessionStore.csvText("line\n\"quoted\""));
		Filepath directory = Filepath.Unchecked.getRooted(temporary.newFolder().toPath());
		Filepath exported = directory.join("export.csv");
		new SessionStore(directory, new Gson()).exportCsv(Arrays.asList(
			session("id", "=1+1", "Lures, \"three\"\nline", 95, 5),
			session("empty", "Fishing", "", 0, 0)), exported);
		String csv = new String(readBytes(exported), StandardCharsets.UTF_8);
		assertTrue(csv.contains("\"'=1+1\""));
		assertTrue(csv.contains("\"Lures, \"\"three\"\"\nline\""));
		assertTrue(csv.contains(",100,95,5,0.95,"));
		assertTrue(csv.contains(",0,0,0,,,,5,2\r\n"));
		assertFalse(csv.contains("NaN"));
	}

	private static AttemptSession session(String id, String activity, String setup, long successes, long failures)
	{
		return new AttemptSession(id, activity, setup, TrackingMethod.TIMED,
			1_790_900_000_000L, 1_790_900_600_000L, successes, failures, 2, 5);
	}
}

package com.attempttracker.store;

import com.attempttracker.core.FishingSession;
import com.google.gson.Gson;
import net.runelite.client.util.Filepath;
import static com.attempttracker.FilepathTestSupport.*;
import java.util.Collections;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

public class FishingSessionStoreTest
{
	@Rule public TemporaryFolder folder = new TemporaryFolder();
	@Test public void csvExportAcceptsAFileScopedChooserSelection() throws Exception
	{
		Filepath directory = Filepath.Unchecked.getRooted(folder.getRoot().toPath());
		Filepath selected = directory.join("selected.csv").rooted();
		assertTrue(selected.isRoot());
		FishingSession session = new FishingSession();
		session.catches = session.measuredCatches = 8;
		new FishingSessionStore(directory, new Gson()).exportCsv(Collections.singletonList(session), selected);
		assertTrue(readString(selected).contains(",8,8,0,0,1.0,1.0,"));
		try (java.util.stream.Stream<Filepath> files = directory.walk(1).filter(path -> !path.equals(directory)))
		{
			assertEquals("Only the user-selected CSV may be created", 1, files.count());
		}
	}
	@Test public void oversizedHistoryRemainsIntactUntilItIsBackedUp() throws Exception
	{
		Filepath directory = Filepath.Unchecked.getRooted(folder.getRoot().toPath());
		Filepath history = directory.join("fishing-sessions.json");
		history.write(new byte[2 * 1024 * 1024 + 1]);
		FishingSessionStore store = new FishingSessionStore(directory, new Gson());
		try { store.load(); fail("Oversized history must be rejected"); }
		catch (java.io.IOException expected) { assertTrue(expected.getMessage().contains("size limit")); }
		assertEquals(2 * 1024 * 1024 + 1, history.size());
		store.save(Collections.singletonList(new FishingSession()));
		try (java.util.stream.Stream<Filepath> files = directory.walk(1))
		{
			Filepath backup = files.filter(path -> path.getFileName().startsWith("fishing-sessions.unreadable-")).findFirst().get();
			assertEquals(2 * 1024 * 1024 + 1, backup.size());
		}
		assertEquals(1, store.load().size());
	}
	@Test public void roundTripKeepsCurrentSessionAndBothClocks() throws Exception
	{
		FishingSessionStore store = new FishingSessionStore(Filepath.Unchecked.getRooted(folder.getRoot().toPath()), new Gson()); assertNull(store.load());
		FishingSession session = new FishingSession(); session.catches = session.measuredCatches = 12; session.minimumFailures = 1; session.maximumFailures = 3;
		session.loggedMillis = 2000; session.fishingMillis = 1000; store.save(Collections.singletonList(session));
		FishingSession restored = store.load().get(0); assertEquals(session.id, restored.id); assertEquals(2000, restored.loggedMillis); assertEquals(1000, restored.fishingMillis); assertEquals(3, restored.maximumFailures);
		Filepath csv = Filepath.Unchecked.getRooted(folder.getRoot().toPath()).join("export.csv"); store.exportCsv(Collections.singletonList(restored), csv);
		String text = readString(csv); assertTrue(text.contains("catch_fail_min,catch_fail_max")); assertTrue(text.contains(",12,12,1,3,0.8,")); assertTrue(text.contains(",2000,1000,0,false"));
	}
	@Test public void malformedHistoryIsBackedUpBeforeNewSave() throws Exception
	{
		Filepath directory = Filepath.Unchecked.getRooted(folder.getRoot().toPath()), file = directory.join("fishing-sessions.json"); file.write("broken");
		FishingSessionStore store = new FishingSessionStore(directory, new Gson());
		try { store.load(); fail("Malformed history must report failure"); } catch (java.io.IOException expected) { }
		store.save(Collections.singletonList(new FishingSession()));
		try (java.util.stream.Stream<Filepath> files = directory.walk(1).filter(path -> !path.equals(directory)))
		{
			Filepath backup = files.filter(path -> path.getFileName().startsWith("fishing-sessions.unreadable-")).findFirst().get(); assertEquals("broken", readString(backup));
		}
	}
}

package com.attempttracker.ui;

import com.attempttracker.core.FishingSession;
import javax.swing.JButton;
import java.awt.Component;
import java.awt.Container;
import java.util.Arrays;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.JList;
import javax.swing.JToggleButton;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.*;

public class AttemptTrackerPanelTest
{
	@Test
	public void hiddenTickUpdatesLeaveSwingComponentsAloneAndReopenWithLatestData() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			AttemptTrackerPanel panel = activePanel(() -> {}, () -> {});
			panel.refresh(Collections.singletonList(session("one", 2)), "Fishing", "Tick 1");
			JList<?> list = find(panel, JList.class);
			AtomicInteger changes = countModelEvents(list);
			JTextArea details = find(panel, JTextArea.class);
			AtomicInteger edits = countDocumentEvents(details);
			panel.onDeactivate();
			for (int i = 3; i <= 200; i++)
			{
				panel.refresh(Collections.singletonList(session("one", i)), "Paused", "Tick " + i,
					new LureDisplay("5 per catch", "Detected automatically", "Live choice"));
			}
			panel.refreshLures(new LureDisplay("None", "No lures available", "No supply"));
			assertEquals(0, changes.get()); assertEquals(0, edits.get());
			assertTrue(hasLabel(panel, "2")); assertFalse(hasLabel(panel, "None"));
			panel.onActivate();
			assertTrue(hasLabel(panel, "200")); assertTrue(hasLabel(panel, "Paused"));
			assertTrue(hasLabel(panel, "None")); assertEquals(1, list.getModel().getSize());
		});
	}

	@Test
	public void clockTicksDoNotRebuildHistoryOrChangeSelection() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			AttemptTrackerPanel panel = activePanel(() -> {}, () -> {});
			FishingSession current = session("one", 7), older = session("older", 3);
			panel.refresh(Arrays.asList(current, older), "Fishing", "Tick 1");
			JList<?> list = find(panel, JList.class);
			AtomicInteger modelChanges = countModelEvents(list), selectionChanges = new AtomicInteger();
			list.addListSelectionListener(event -> selectionChanges.incrementAndGet());
			current.loggedMillis = 9000; current.fishingMillis = 6000; current.fishingTicks = 10;
			panel.refresh(Arrays.asList(current, older), "Fishing", "Tick 2");
			assertEquals(0, modelChanges.get()); assertEquals(0, selectionChanges.get());
			assertTrue(hasLabel(panel, "00:00:09")); assertTrue(hasLabel(panel, "00:00:06"));
			assertTrue(hasLabel(panel, "Fishing ticks: 10"));
			list.setSelectedIndex(1); list.setSelectedIndex(0);
			assertTrue(hasLabel(panel, "00:00:09"));
			current.catches++; current.measuredCatches++;
			panel.refresh(Arrays.asList(current, older), "Fishing", "Tick 3");
			assertEquals(1, modelChanges.get()); assertTrue(hasLabel(panel, "8"));
		});
	}

	@Test
	public void foldedDetailsAvoidDocumentEditsAndExpandedDetailsDoNotAutoScroll() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			AttemptTrackerPanel panel = activePanel(() -> {}, () -> {});
			JTextArea details = find(panel, JTextArea.class);
			AtomicInteger edits = countDocumentEvents(details);
			panel.refresh(Collections.singletonList(session("one", 1)), "Fishing", "Tick 1");
			panel.refresh(Collections.singletonList(session("one", 1)), "Fishing", "Tick 2");
			assertEquals(0, edits.get());
			findToggle(panel, "Details").doClick();
			assertEquals("Tick 2", details.getText());
			assertEquals(javax.swing.text.DefaultCaret.NEVER_UPDATE, ((javax.swing.text.DefaultCaret) details.getCaret()).getUpdatePolicy());
			int before = edits.get();
			panel.refresh(Collections.singletonList(session("one", 1)), "Fishing", "Tick 2");
			assertEquals(before, edits.get());
			panel.refresh(Collections.singletonList(session("one", 1)), "Fishing", "Tick 3");
			assertEquals("Tick 3", details.getText());
		});
	}

	private static AttemptTrackerPanel activePanel(Runnable reset, Runnable export)
	{
		AttemptTrackerPanel panel = new AttemptTrackerPanel(reset, export); panel.onActivate(); return panel;
	}
	private static AtomicInteger countModelEvents(JList<?> list)
	{
		AtomicInteger changes = new AtomicInteger();
		list.getModel().addListDataListener(new javax.swing.event.ListDataListener()
		{
			public void intervalAdded(javax.swing.event.ListDataEvent event) { changes.incrementAndGet(); }
			public void intervalRemoved(javax.swing.event.ListDataEvent event) { changes.incrementAndGet(); }
			public void contentsChanged(javax.swing.event.ListDataEvent event) { changes.incrementAndGet(); }
		});
		return changes;
	}
	private static AtomicInteger countDocumentEvents(JTextArea details)
	{
		AtomicInteger edits = new AtomicInteger();
		details.getDocument().addDocumentListener(new javax.swing.event.DocumentListener()
		{
			public void insertUpdate(javax.swing.event.DocumentEvent event) { edits.incrementAndGet(); }
			public void removeUpdate(javax.swing.event.DocumentEvent event) { edits.incrementAndGet(); }
