	private static void assertSuccessOnly(AttemptSession session, long successes)
	{
		assertNotNull(session);
		assertEquals(TrackingMethod.SUCCESS_ONLY, session.getMethod());
		assertEquals(successes, session.getSuccesses());
		assertEquals(0L, session.getFailures());
		assertEquals(0L, session.getAttempts());
		assertTrue(Double.isNaN(session.getSuccessRate()));
		assertTrue(Double.isNaN(session.getConfidenceLower()));
		assertTrue(Double.isNaN(session.getConfidenceUpper()));
	}

	private static void assertCounts(AttemptSession session, long successes, long failures,
		int excluded)
	{
		assertNotNull(session);
		assertEquals(successes, session.getSuccesses());
		assertEquals(failures, session.getFailures());
		assertEquals(successes + failures, session.getAttempts());
		assertEquals(excluded, session.getExcludedWindows());
	}

	private static void set(Object object, String name, Object value) throws Exception
	{
		Field field = object.getClass().getDeclaredField(name);
		field.setAccessible(true);
		field.set(object, value);
	}

	private static Object get(Object object, String name) throws Exception
	{
		Field field = object.getClass().getDeclaredField(name);
		field.setAccessible(true);
		return field.get(object);
	}

	private static void optionalSet(Object object, String name, Object value) throws Exception
	{
		try { set(object, name, value); }
		catch (NoSuchFieldException ignored) { /* New optional injected service. */ }
	}

	private static void invoke(Object object, String name) throws Exception
	{
		Method method = object.getClass().getDeclaredMethod(name);
		method.setAccessible(true);
		method.invoke(object);
	}

	private static final class Harness
	{
		private final AttemptTrackerPlugin plugin = new AttemptTrackerPlugin();
		private final Client client = mock(Client.class);
		private final Player player = mock(Player.class);
		private final NPC spot = mock(NPC.class);
		private final WorldView worldView = mock(WorldView.class);
		private final AttemptTrackerConfig config = mock(AttemptTrackerConfig.class, CALLS_REAL_METHODS);
		private final ItemManager itemManager = mock(ItemManager.class);
		private final ClientThread clientThread = mock(ClientThread.class);
		private final ItemContainer inventory = mock(ItemContainer.class);
		private final EnumMap<Skill, Integer> experience = new EnumMap<>(Skill.class);
		private final AttemptTrackerEngine engine;
		private int currentTick;

		private Harness(boolean fixedTiming) throws Exception
		{
			when(client.getLocalPlayer()).thenReturn(player);
			when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
			when(client.getTickCount()).thenAnswer(call -> currentTick);
			when(client.getSkillExperience(any(Skill.class))).thenAnswer(call -> experience.getOrDefault(call.getArgument(0), 0));
			when(client.getRealSkillLevel(any(Skill.class))).thenReturn(99);
			when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
			when(client.getVarbitValue(VarbitID.SHARK_LURE_USE_QUANTITY)).thenReturn(1);
			when(player.getName()).thenReturn("Attempt Tester");
			when(player.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));
			when(player.getWorldView()).thenReturn(worldView);
			when(player.getAnimation()).thenReturn(AnimationID.HUMAN_HARPOON_CRYSTAL);
			when(player.getInteracting()).thenReturn(spot);
			when(spot.getId()).thenReturn(FishingSpot.SHARK.getIds()[0]);
			when(spot.getName()).thenReturn("Fishing spot");
			when(spot.getWorldLocation()).thenReturn(new WorldPoint(3200, 3201, 0));
			when(spot.getWorldView()).thenReturn(worldView);
			when(config.fixedTiming()).thenReturn(fixedTiming);
			// Historical fixtures exercise their explicit manual timing declarations.
			when(config.autoDetectLures()).thenReturn(false);
			// Earlier phase fixtures deliberately configure a five-tick first roll.
			// Live/default fixtures explicitly restore automatic mode (zero).
			when(config.sharkFirstRollDelay()).thenReturn(5);
			when(inventory.getItems()).thenReturn(new Item[]{new Item(ItemID.SHARK_LURE, 300)});
			when(inventory.count(ItemID.SHARK_LURE)).thenReturn(300);
			when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
			ItemContainer equipment = mock(ItemContainer.class);
			when(equipment.getItems()).thenReturn(new Item[0]);
			when(client.getItemContainer(InventoryID.WORN)).thenReturn(equipment);
			ItemComposition lure = mock(ItemComposition.class);
			when(lure.getName()).thenReturn("Shark lure");
			when(itemManager.getItemComposition(anyInt())).thenReturn(lure);
			set(plugin, "client", client);
			set(plugin, "config", config);
			set(plugin, "itemManager", itemManager);
			doAnswer(call -> { ((Runnable) call.getArgument(0)).run(); return null; })
				.when(clientThread).invoke(any(Runnable.class));
			set(plugin, "clientThread", clientThread);
			optionalSet(plugin, "configManager", mock(ConfigManager.class));
			set(plugin, "custom", new CustomActivity(config));
			set(plugin, "running", true);
			set(plugin, "lastAccount", player.getName());
			engine = (AttemptTrackerEngine) get(plugin, "engine");
		}

		private void enableCustom() throws Exception
		{
			when(config.customEnabled()).thenReturn(true);
			when(config.customMode()).thenReturn(AttemptTrackerConfig.CustomMode.TIMED);
			when(config.customName()).thenReturn("Custom shark");
			when(config.customSkill()).thenReturn(Skill.FISHING);
			when(config.customSuccess()).thenReturn("A custom success");
			when(config.customStart()).thenReturn("A custom start");
			when(config.customAnimations()).thenReturn(Integer.toString(AnimationID.HUMAN_HARPOON_CRYSTAL));
			when(config.customCycle()).thenReturn(5);
			set(plugin, "custom", new CustomActivity(config));
		}

		private void chat(ChatMessageType type, String text)
		{
			ChatMessage message = new ChatMessage();
			message.setType(type);
			message.setMessage(text);
			plugin.onChatMessage(message);
		}

		private void catchMessage()
		{
			chat(ChatMessageType.SPAM, "You catch a shark.");
			experience.put(Skill.FISHING, experience.getOrDefault(Skill.FISHING, 0) + 110);
		}

		private void liveIslandSharks()
		{
			// Exact live NPC: gameval NpcID._0_40_34_MEMBERFISH, omitted by FishingSpot.
			when(spot.getId()).thenReturn(16335);
			when(spot.getWorldLocation()).thenReturn(new WorldPoint(2576, 2219, 0));
			when(player.getWorldLocation()).thenReturn(new WorldPoint(2575, 2219, 0));
			when(config.sharkFirstRollDelay()).thenReturn(0);
			ItemContainer equipment = mock(ItemContainer.class);
			when(equipment.getItems()).thenReturn(new Item[]{new Item(ItemID.CRYSTAL_HARPOON, 1)});
			when(client.getItemContainer(InventoryID.WORN)).thenReturn(equipment);
		}

		private void liveIslandCatch()
		{
			chat(ChatMessageType.SPAM, "You catch a shark!");
			experience.put(Skill.FISHING, experience.getOrDefault(Skill.FISHING, 0) + 22);
			int remaining = inventory.count(ItemID.SHARK_LURE) - 3;
			when(inventory.count(ItemID.SHARK_LURE)).thenReturn(remaining);
			when(inventory.getItems()).thenReturn(new Item[]{new Item(ItemID.SHARK_LURE, remaining)});
		}

		private void startSharks()
		{
			chat(ChatMessageType.SPAM, "You start harpooning fish.");
		}

		private void startCustom()
		{
			chat(ChatMessageType.SPAM, "A custom start occurred.");
		}

		private void interaction(Actor source, Actor target)
		{
			plugin.onInteractingChanged(new InteractingChanged(source, target));
		}

		private void clickNpc(NPC npc, String option)
		{
			MenuEntry entry = mock(MenuEntry.class);
			when(entry.getType()).thenReturn(MenuAction.NPC_SECOND_OPTION);
			when(entry.getOption()).thenReturn(option);
			when(entry.getTarget()).thenReturn("<col=ffff00>Fishing spot</col>");
			when(entry.getNpc()).thenReturn(npc);
			plugin.onMenuOptionClicked(new MenuOptionClicked(entry));
		}

		private void tick(int tick)
		{
			assertEquals("Harness must observe every tick in order", currentTick, tick);
			plugin.onGameTick(new GameTick());
			// Hooks.tick increments only after GameTick subscribers have run. Chat
			// packets before the next GameTick therefore see its current counter.
			currentTick = tick + 1;
		}

		private void ticks(int first, int last, int... successfulTicks)
		{
			for (int tick = first; tick <= last; tick++)
			{
				for (int successfulTick : successfulTicks)
				{
					if (tick == successfulTick) { catchMessage(); }
				}
				tick(tick);
			}
		}

		private AttemptSession find(TrackingMethod method)
		{
			for (AttemptSession session : engine.getSessions())
			{
				if (session.getMethod() == method) { return session; }
			}
			fail("Missing " + method + " session");
			return null;
		}

		private AttemptSession find(TrackingMethod method, String setupFragment)
		{
			for (AttemptSession session : engine.getSessions())
			{
				if (session.getMethod() == method && session.getSetup().contains(setupFragment)) { return session; }
			}
			fail("Missing " + method + " session with setup " + setupFragment);
			return null;
		}

		private long successOnlyCatchCount()
		{
			long count = 0;
			for (AttemptSession session : engine.getSessions())
			{
				if (session.getMethod() == TrackingMethod.SUCCESS_ONLY) { count += session.getSuccesses(); }
			}
			return count;
		}
	}
}

package com.attempttracker.store;

import com.attempttracker.core.FishingSession;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.util.List;
import net.runelite.client.util.Filepath;

/** Separate file preserves the legacy per-setup history during the UI migration. */
public final class FishingSessionStore
{
	private final Filepath file;
	private final Gson gson;
	private boolean preserveUnreadable;
	public FishingSessionStore(Filepath directory, Gson gson) { file = directory.join("fishing-sessions.json"); this.gson = gson; }
	public synchronized List<FishingSession> load() throws IOException
	{
		if (!file.exists()) { return null; }
		preserveUnreadable = true;
		if (file.size() > 2 * 1024 * 1024) { throw new IOException("Fishing session file exceeds size limit"); }
		byte[] bytes;
		try (InputStream stream = file.openInputStream())
		{
			bytes = stream.readNBytes(2 * 1024 * 1024 + 1);
		}
		if (bytes.length > 2 * 1024 * 1024) { throw new IOException("Fishing session file exceeds size limit"); }
		try
		{
			List<FishingSession> saved = gson.fromJson(new String(bytes, StandardCharsets.UTF_8), new TypeToken<List<FishingSession>>() {}.getType());
			if (saved == null) { throw new IllegalArgumentException("Expected a session array"); }
			preserveUnreadable = false; return saved;
		}
		catch (RuntimeException ex) { throw new IOException("Fishing sessions could not be read", ex); }
	}
	public synchronized void save(List<FishingSession> sessions) throws IOException
	{
		byte[] bytes = gson.toJson(sessions.subList(0, Math.min(200, sessions.size()))).getBytes(StandardCharsets.UTF_8);
		if (bytes.length > 2 * 1024 * 1024) { throw new IOException("Fishing session file exceeds size limit"); }
		file.getParent().createDirectories();
		if (preserveUnreadable && file.exists())
		{
			Filepath backup = file.getParent().createTempFile("fishing-sessions.unreadable-", ".json");
			try { file.copyTo(backup, StandardCopyOption.REPLACE_EXISTING); }
			catch (IOException ex) { backup.deleteIfExists(); throw ex; }
			preserveUnreadable = false;
		}
		SessionStore.writeAtomically(file, bytes);
	}
	public void exportCsv(List<FishingSession> sessions, Filepath destination) throws IOException
	{
		StringBuilder csv = new StringBuilder("session_id,started_at_utc,ended_at_utc,catch_success,measured_catches,catch_fail_min,catch_fail_max,catch_rate_min,catch_rate_max,logged_in_ms,fishing_ms,fishing_ticks,variable_timing\r\n");
		for (FishingSession session : sessions)
		{
			csv.append(SessionStore.csvText(session.id)).append(',')
				.append(SessionStore.csvText(Instant.ofEpochMilli(session.startedAt).toString())).append(',')
				.append(SessionStore.csvText(session.endedAt == 0 ? "" : Instant.ofEpochMilli(session.endedAt).toString())).append(',')
				.append(session.catches).append(',').append(session.measuredCatches).append(',')
				.append(session.minimumFailures).append(',').append(session.maximumFailures).append(',')
				.append(rate(session.rate(false))).append(',').append(rate(session.rate(true))).append(',')
				.append(session.loggedMillis).append(',').append(session.fishingMillis).append(',')
				.append(session.fishingTicks).append(',').append(session.variableTiming).append("\r\n");
		}
		// The chooser authorizes only this file; do not access its parent or siblings.
		destination.write(csv.toString());
	}
	private static String rate(double value) { return Double.isFinite(value) ? Double.toString(value) : ""; }
}

package com.attempttracker.store;

import com.attempttracker.core.AttemptSession;
import com.attempttracker.core.TrackingMethod;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import net.runelite.client.util.Filepath;

/** Local, bounded session persistence. The tracking engine validates restored sessions. */
public final class SessionStore
{
	private static final int FORMAT_VERSION = 1;
	private static final int MAX_SESSIONS = 200;
	private static final int MAX_FILE_BYTES = 2 * 1024 * 1024;
	private final Filepath directory;
	private final Gson gson;
	private String lastLoadWarning = "";
	private boolean preserveUnreadableHistory;

	public SessionStore(Filepath directory, Gson gson)
	{
		this.directory = Objects.requireNonNull(directory);
		this.gson = Objects.requireNonNull(gson);
	}

	/** Corrupt or unsupported data returns an empty history and leaves the source file intact. */
	public synchronized List<AttemptSession> load() throws IOException
	{
		lastLoadWarning = "";
		preserveUnreadableHistory = false;
		Filepath file = directory.join("sessions.json");
		if (!file.exists())
		{
			return Collections.emptyList();
		}
		if (file.size() > MAX_FILE_BYTES)
		{
			lastLoadWarning = "Saved history exceeds the size limit.";
			preserveUnreadableHistory = true;
			return Collections.emptyList();
		}
		byte[] bytes;
		try (InputStream stream = file.openInputStream())
		{
			bytes = stream.readNBytes(MAX_FILE_BYTES + 1);
		}
		if (bytes.length > MAX_FILE_BYTES)
		{
			lastLoadWarning = "Saved history exceeds the size limit.";
			preserveUnreadableHistory = true;
			return Collections.emptyList();
		}
		try
		{
			JsonElement parsed = new JsonParser().parse(new String(bytes, StandardCharsets.UTF_8));
			if (!parsed.isJsonObject())
			{
				throw new JsonParseException("Expected a history object");
			}
			JsonObject root = parsed.getAsJsonObject();
			if (!root.has("version") || root.get("version").getAsInt() != FORMAT_VERSION
				|| !root.has("sessions") || !root.get("sessions").isJsonArray())
			{
				lastLoadWarning = "Saved history has an unsupported format.";
				preserveUnreadableHistory = true;
				return Collections.emptyList();
			}
			List<AttemptSession> sessions = new ArrayList<>();
			for (JsonElement element : root.getAsJsonArray("sessions"))
			{
				if (sessions.size() >= MAX_SESSIONS)
				{
					break;
				}
				if (!element.isJsonObject())
				{
					lastLoadWarning = "Some invalid history entries were skipped.";
					preserveUnreadableHistory = true;
					continue;
				}
				try
				{
					AttemptSession session = gson.fromJson(element, AttemptSession.class);
					if (session != null)
					{
						sessions.add(session);
					}
				}
				catch (RuntimeException ex)
				{
					lastLoadWarning = "Some invalid history entries were skipped.";
					preserveUnreadableHistory = true;
				}
			}
			return sessions;
		}
		catch (RuntimeException ex)
		{
			lastLoadWarning = "Saved history could not be read; a new session will be started.";
			preserveUnreadableHistory = true;
			return Collections.emptyList();
		}
	}

	public synchronized String getLastLoadWarning()
	{
		return lastLoadWarning;
	}

	public synchronized void save(List<AttemptSession> sessions) throws IOException
	{
		JsonObject root = new JsonObject();
		root.addProperty("version", FORMAT_VERSION);
		JsonArray items = new JsonArray();
		for (AttemptSession session : bounded(sessions))
		{
			items.add(gson.toJsonTree(session));
		}
		root.add("sessions", items);
		byte[] bytes = gson.toJson(root).getBytes(StandardCharsets.UTF_8);
		if (bytes.length > MAX_FILE_BYTES)
		{
			throw new IOException("Session history exceeds the size limit");
		}
		directory.createDirectories();
		Filepath destination = directory.join("sessions.json");
		if (preserveUnreadableHistory && destination.exists())
		{
			// Copy before replacing so a failed backup never destroys the original history.
			Filepath backup = directory.createTempFile("sessions.unreadable-" + System.currentTimeMillis() + "-", ".json");
			try
			{
				destination.copyTo(backup, StandardCopyOption.REPLACE_EXISTING);
			}
			catch (IOException ex)
			{
				backup.deleteIfExists();
				throw ex;
			}
			preserveUnreadableHistory = false;
		}
		writeAtomically(destination, bytes);
	}

	/** CSV rates are proportions (0..1). Text is protected against spreadsheet formulas. */
	public void exportCsv(List<AttemptSession> sessions, Filepath destination) throws IOException
	{
		StringBuilder csv = new StringBuilder("session_id,activity,setup,method,started_at_utc,updated_at_utc,attempts,successes,failures,success_rate,ci95_lower,ci95_upper,cycle_ticks,excluded_windows\r\n");
		for (AttemptSession session : bounded(sessions))
		{
			boolean successesOnly = session.getMethod() == TrackingMethod.SUCCESS_ONLY;
			csv.append(csvText(session.getId())).append(',')
				.append(csvText(session.getActivity())).append(',')
				.append(csvText(session.getSetup())).append(',')
				.append(csvText(session.getMethod() == null ? "" : session.getMethod().name())).append(',')
				.append(csvText(Instant.ofEpochMilli(session.getStartedAt()).toString())).append(',')
				.append(csvText(Instant.ofEpochMilli(session.getUpdatedAt()).toString())).append(',')
				.append(successesOnly ? "" : Long.toString(session.getAttempts())).append(',')
				.append(session.getSuccesses()).append(',')
				.append(successesOnly ? "" : Long.toString(session.getFailures())).append(',')
				.append(csvRate(session.getSuccessRate())).append(',')
				.append(csvRate(session.getConfidenceLower())).append(',')
				.append(csvRate(session.getConfidenceUpper())).append(',')
				.append(session.getCycleTicks()).append(',')
				.append(session.getExcludedWindows()).append("\r\n");
		}
		// A chooser grants access to the selected file only, not its siblings.
		Objects.requireNonNull(destination).write(csv.toString());
	}

	static String csvText(String text)
	{
		String value = text == null ? "" : text;
		int first = 0;
		while (first < value.length() && Character.isWhitespace(value.charAt(first)))
		{
			first++;
		}
		if ((first < value.length() && "=+-@".indexOf(value.charAt(first)) >= 0)
			|| (!value.isEmpty() && (value.charAt(0) == '\t' || value.charAt(0) == '\r' || value.charAt(0) == '\n')))
		{
			value = "'" + value;
		}
		return '"' + value.replace("\"", "\"\"") + '"';
	}

	private static String csvRate(double rate)
	{
		return Double.isFinite(rate) ? Double.toString(rate) : "";
	}

	private static List<AttemptSession> bounded(List<AttemptSession> sessions)
	{
		Objects.requireNonNull(sessions);
		List<AttemptSession> result = new ArrayList<>();
		for (AttemptSession session : sessions)
		{
			if (result.size() >= MAX_SESSIONS)
			{
				break;
			}
			if (session != null)
			{
				result.add(session.copy());
			}
		}
		return result;
	}

	static void writeAtomically(Filepath destination, byte[] bytes) throws IOException
	{
		Filepath temporary = destination.getParent().createTempFile("attempt-tracker-", ".tmp");
		try
		{
			temporary.write(bytes);
			try
			{
				temporary.moveTo(destination, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
			}
			catch (AtomicMoveNotSupportedException ex)
			{
				temporary.moveTo(destination, StandardCopyOption.REPLACE_EXISTING);
			}
		}
		finally
		{
			temporary.deleteIfExists();
		}
	}
}

package com.attempttracker.diagnostics;

import java.io.BufferedWriter;
import java.io.Closeable;
import java.io.IOException;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import net.runelite.client.util.Filepath;

/** Local per-tick trace, called only from the plugin's serial I/O worker. */
public final class TickTrace implements Closeable
{
	private static final int MAX_ROWS = 100_000;
	private final Filepath directory;
	private BufferedWriter writer;
	private int rows;
	public TickTrace(Filepath directory) { this.directory = directory; }
	public void append(String row) throws IOException
	{
		if (writer == null || rows == MAX_ROWS)
		{
			close(); directory.createDirectories();
			Filepath file = directory.join("ticks-" + LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss-SSS")) + ".csv");
			writer = file.openBufferedWriter(StandardOpenOption.CREATE_NEW);
			writer.write("time_utc,tick,animation,frame,skill,target,xp_delta,inventory_lures,raw_lure_setting,configured_cycle,first_roll_delay,success_messages,eligible,start_tick,timing_result,live_interaction,context_problem,start_message,start_message_tick\r\n"); rows = 0;
		}
		writer.write(row); rows++;
		writer.flush();
	}
	public static String row(int tick, int animation, int frame, String skill, String target, int xpDelta,
		int lures, int rawSetting, int cycle, int firstDelay, int successes, boolean eligible, int startTick, String timingResult,
		String liveInteraction, String contextProblem, String startMessage, int startMessageTick)
	{
		return Instant.now() + "," + tick + "," + animation + "," + frame + "," + quoted(skill) + "," + quoted(target)
			+ "," + xpDelta + "," + lures + "," + rawSetting + "," + cycle + "," + firstDelay + "," + successes + "," + eligible
			+ "," + startTick + "," + quoted(timingResult) + "," + quoted(liveInteraction) + "," + quoted(contextProblem)
			+ "," + quoted(startMessage) + "," + startMessageTick + "\r\n";
	}
	private static String quoted(String text) { String value = text == null ? "" : text; return "\"" + value.replace("\"", "\"\"") + "\""; }
	@Override public void close() throws IOException { if (writer != null) { try { writer.close(); } finally { writer = null; rows = 0; } } }
}

