package com.attempttracker.core;

import java.util.UUID;

/** User-controlled session: logout, gear changes and new spots never reset it. */
public final class FishingSession
{
	public String id = UUID.randomUUID().toString();
	public long startedAt = System.currentTimeMillis();
	public long endedAt;
	public long catches;
	public long measuredCatches;
	public long minimumFailures;
	public long maximumFailures;
	public long loggedMillis;
	public long fishingMillis;
	public long fishingTicks;
	public boolean variableTiming;

	public FishingSession copy()
	{
		FishingSession copy = new FishingSession();
		copy.id = id; copy.startedAt = startedAt; copy.endedAt = endedAt;
		copy.catches = catches; copy.measuredCatches = measuredCatches;
		copy.minimumFailures = minimumFailures; copy.maximumFailures = maximumFailures;
		copy.loggedMillis = loggedMillis; copy.fishingMillis = fishingMillis; copy.fishingTicks = fishingTicks;
		copy.variableTiming = variableTiming;
		return copy;
	}
	public double rate(boolean upper)
	{
		// Unanchored catches remain in the total but cannot supply a denominator.
		if (measuredCatches + maximumFailures == 0) { return Double.NaN; }
		long failures = upper ? minimumFailures : maximumFailures;
		return measuredCatches == 0 ? 0 : measuredCatches / ((double) measuredCatches + failures);
	}
}

package com.attempttracker.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.UUID;
import java.util.function.LongSupplier;

/**
 * Counting and session history without client dependencies.
 *
 * Timed mode requires an explicit action start and one observation every game
 * tick. A start at T with first delay D makes T + D the first attempt deadline;
 * subsequent deadlines are C ticks apart. Each uninterrupted deadline
 * contributes one success or one inferred failure.
 * Missing ticks, off-deadline outcomes, configuration changes and interruption
 * discard the unfinished cycle. Excluded windows are discarded timing windows,
 * not known failed attempts. An invalid timer requires another explicit start.
 * Ambiguous timing rolls back the latest start's estimated trials and preserves
 * its visible catches separately. Intentional interruption keeps completed trials.
 */
public final class AttemptTrackerEngine
{
	private static final int MAX_HISTORY = 200;

	/** Result of a tick observation; rejected successes remain the caller's responsibility. */
	public enum TimedResult
	{
		/** No active start-anchored timer; outcomes have not been counted. */
		WAITING_FOR_START,
		/** Accepted tick without a new completed attempt (also duplicate ticks). */
		WAITING,
		/** Exactly one complete active cycle has entered the denominator. */
		COUNTED,
		/** Timing stopped; any successfulRolls in this call remain uncounted. */
		INVALIDATED
	}

	private final LongSupplier clock;
	private final List<AttemptSession> sessions = new ArrayList<>();
	private final Map<Profile, AttemptSession> activeProfiles = new HashMap<>();
	private AttemptSession currentSession;
	private Profile timedProfile;
	private AttemptSession timedSession;
	private int boundaryTick;
	private long nextDeadlineTick;
	private int lastTick;
	private boolean observedLastTick;
	private long startSuccesses;
	private long startFailures;

	public AttemptTrackerEngine()
	{
		this(System::currentTimeMillis);
	}

	AttemptTrackerEngine(LongSupplier clock)
	{
		this.clock = Objects.requireNonNull(clock, "clock");
	}

	/** Loads validated history. Restored sessions do not resume old timing/grouping. */
	public synchronized void restore(List<AttemptSession> restored)
	{
		clear();
		if (restored == null)
		{
			return;
		}
		long now = now();
		List<AttemptSession> valid = new ArrayList<>();
		for (AttemptSession value : restored)
		{
			AttemptSession sanitized = sanitize(value, now);
			if (sanitized != null)
			{
				valid.add(sanitized);
			}
		}
		valid.sort(Comparator.comparingLong(AttemptSession::getUpdatedAt).reversed()
			.thenComparing(Comparator.comparingLong(AttemptSession::getStartedAt).reversed()));
		Set<String> ids = new HashSet<>();
		for (AttemptSession value : valid)
		{
			if (ids.add(value.getId()))
			{
				sessions.add(value);
				if (sessions.size() == MAX_HISTORY)
				{
					break;
				}
			}
		}
	}

	public synchronized List<AttemptSession> getSessions()
	{
		List<AttemptSession> snapshots = new ArrayList<>(sessions.size());
		for (AttemptSession session : sessions)
		{
			snapshots.add(session.copy());
		}
		return Collections.unmodifiableList(snapshots);
	}

	public synchronized AttemptSession getCurrentSession()
	{
		return currentSession == null ? null : currentSession.copy();
	}

	public synchronized void recordObserved(String activity, String setup, boolean success)
	{
		Profile profile = new Profile(requiredActivity(activity), normalizedSetup(setup),
			TrackingMethod.OBSERVED, 0);
		AttemptSession session = sessionFor(profile);
		session.addCounts(success ? 1 : 0, success ? 0 : 1, now());
		makeLatest(session);
	}

	/** Records catches without claiming that failed rolls or total attempts are known. */
	public synchronized void recordSuccessOnly(String activity, String setup)
	{
		recordSuccessOnly(activity, setup, 1);
	}

	/** Preserves a batch of visible outcomes without an attempt denominator. */
	public synchronized void recordSuccessOnly(String activity, String setup, long successfulRolls)
	{
		if (successfulRolls < 0)
		{
			throw new IllegalArgumentException("successfulRolls must be nonnegative");
		}
		Profile profile = new Profile(requiredActivity(activity), normalizedSetup(setup),
			TrackingMethod.SUCCESS_ONLY, 0);
		if (successfulRolls == 0)
		{
			return;
		}
		AttemptSession session = sessionFor(profile);
		session.addCounts(successfulRolls, 0, now());
		makeLatest(session);
	}

	/**
	 * Starts or restarts a timer from an explicit action-start signal. The first
	 * deadline is tick + cycleTicks; the start tick is not an attempt. Call this
	 * before observeTimed when both events belong to the same game tick.
	 */
	public synchronized void startTimed(int tick, String activity, String setup, int cycleTicks)
	{
		startTimed(tick, activity, setup, cycleTicks, cycleTicks);
	}

	/** Starts a timer with a separately validated delay before its first attempt. */
	public synchronized void startTimed(int tick, String activity, String setup, int cycleTicks,
		int firstDelayTicks)
	{
		Profile profile = timedProfile(activity, setup, cycleTicks);
		if (firstDelayTicks < 1 || firstDelayTicks > 100)
		{
			throw new IllegalArgumentException("firstDelayTicks must be between 1 and 100");
		}
		discardTiming(false, tick);
		timedProfile = profile;
		timedSession = sessionFor(profile);
		boundaryTick = tick;
		nextDeadlineTick = (long) tick + firstDelayTicks;
		lastTick = tick;
		observedLastTick = false;
		startSuccesses = 0;
		startFailures = 0;
		timedSession.touch(now());
		makeLatest(timedSession);
	}

	public synchronized boolean isTimingActive()
	{
		return timedSession != null;
	}

	/**
	 * Supply every game tick, with zero successfulRolls when no catch occurred.
	 * COUNTED means this tick completed one active cycle. WAITING includes the
	 * start tick, intervening ticks and ignored duplicate observations. Outcomes
	 * before or between deadlines invalidate timing, as do multiple successes,
	 * missing ticks and profile changes. None establishes a replacement anchor.
	 * Ambiguity rolls back trials since the latest start and preserves their
	 * visible catches as SUCCESS_ONLY. An ineligible observation intentionally
	 * interrupts instead: completed trials remain. Ineligible observations do not
	 * require activity/setup/cadence values.
	 */
	public synchronized TimedResult observeTimed(int tick, String activity, String setup,
		int cycleTicks, boolean eligible, int successfulRolls)
	{
		if (successfulRolls < 0)
		{
			throw new IllegalArgumentException("successfulRolls must be nonnegative");
		}
		if (!eligible)
		{
			boolean wasActive = isTimingActive();
			discardTiming(false, tick);
			return wasActive ? TimedResult.INVALIDATED : TimedResult.WAITING_FOR_START;
		}
		Profile profile = timedProfile(activity, setup, cycleTicks);
		if (!isTimingActive())
		{
			return TimedResult.WAITING_FOR_START;
		}
		long difference = (long) tick - lastTick;
		if (difference == 0 && observedLastTick)
		{
			return TimedResult.WAITING;
		}
		if ((difference != 1 && !(difference == 0 && !observedLastTick))
			|| !profile.equals(timedProfile) || successfulRolls > 1)
		{
			discardTiming(true, tick);
			return TimedResult.INVALIDATED;
		}
		lastTick = tick;
		observedLastTick = true;
		if ((long) tick < nextDeadlineTick)
		{
			if (successfulRolls != 0)
			{
				discardTiming(true, tick);
				return TimedResult.INVALIDATED;
			}
			return TimedResult.WAITING;
		}
		// Never fill unknown cycles or accept an outcome after its deadline.
		if ((long) tick != nextDeadlineTick
			|| !timedSession.addCounts(successfulRolls, successfulRolls == 0 ? 1 : 0, now()))
		{
			discardTiming(true, tick);
			return TimedResult.INVALIDATED;
		}
		boundaryTick = tick;
		nextDeadlineTick = (long) tick + cycleTicks;
		startSuccesses += successfulRolls;
		startFailures += successfulRolls == 0 ? 1 : 0;
		makeLatest(timedSession);
		return TimedResult.COUNTED;
	}

	public synchronized void interruptTiming()
	{
		discardTiming(false, lastTick);
	}

	/**
	 * Rejects ambiguous timing evidence detected by the client adapter. Unlike an
	 * intentional stop, this rolls back the latest start's estimated trials and
	 * preserves its already counted visible catches without a denominator.
	 */
	public synchronized TimedResult invalidateTiming(int tick)
	{
		if (!isTimingActive())
		{
			return TimedResult.WAITING_FOR_START;
		}
		discardTiming(true, tick);
		return TimedResult.INVALIDATED;
	}

	/** Begins new grouping while retaining historical session snapshots. */
	public synchronized void startNewSession()
	{
		interruptTiming();
		activeProfiles.clear();
		currentSession = null;
	}

	public synchronized void clear()
	{
		sessions.clear();
		activeProfiles.clear();
		currentSession = null;
		timedProfile = null;
		timedSession = null;
		observedLastTick = false;
		startSuccesses = 0;
		startFailures = 0;
	}

	private void discardTiming(boolean ambiguous, int interruptionTick)
	{
		long preservedSuccesses = ambiguous ? startSuccesses : 0;
		Profile discardedProfile = timedProfile;
		if (ambiguous && timedSession != null
			&& !timedSession.removeCounts(startSuccesses, startFailures, now()))
		{
			throw new IllegalStateException("timed contributions exceed session counters");
		}
		if (timedSession != null
			&& (ambiguous || (long) interruptionTick > boundaryTick || (long) lastTick > boundaryTick))
		{
			timedSession.excludeWindow(now());
			makeLatest(timedSession);
		}
		timedSession = null;
		timedProfile = null;
		observedLastTick = false;
		startSuccesses = 0;
		startFailures = 0;
		if (preservedSuccesses != 0 && discardedProfile != null)
		{
			recordSuccessOnly(discardedProfile.activity, discardedProfile.setup, preservedSuccesses);
		}
	}

	private AttemptSession sessionFor(Profile profile)
	{
		AttemptSession session = activeProfiles.get(profile);
		if (session == null)
		{
			long now = now();
			session = new AttemptSession(UUID.randomUUID().toString(), profile.activity,
				profile.setup, profile.method, now, now, 0, 0, 0, profile.cycleTicks);
			activeProfiles.put(profile, session);
			sessions.add(0, session);
			trimHistory();
		}
		return session;
	}

	private void makeLatest(AttemptSession session)
	{
		sessions.remove(session);
		sessions.add(0, session);
		currentSession = session;
	}

	private void trimHistory()
	{
		while (sessions.size() > MAX_HISTORY)
		{
			AttemptSession removed = sessions.remove(sessions.size() - 1);
			activeProfiles.values().removeIf(value -> value == removed);
			if (timedSession == removed)
			{
				timedSession = null;
				timedProfile = null;
				observedLastTick = false;
				startSuccesses = 0;
				startFailures = 0;
			}
		}
	}

	private long now()
	{
		return Math.max(0L, clock.getAsLong());
	}

	private static String requiredActivity(String activity)
	{
		if (activity == null || activity.trim().isEmpty())
		{
			throw new IllegalArgumentException("activity must not be blank");
		}
		return activity.trim();
	}

	private static String normalizedSetup(String setup)
	{
		return setup == null ? "" : setup.trim();
	}

	private static Profile timedProfile(String activity, String setup, int cycleTicks)
	{
		if (cycleTicks < 1)
		{
			throw new IllegalArgumentException("cycleTicks must be positive");
		}
		return new Profile(requiredActivity(activity), normalizedSetup(setup),
			TrackingMethod.TIMED, cycleTicks);
	}

	private static AttemptSession sanitize(AttemptSession value, long now)
	{
		if (value == null || value.getActivity() == null || value.getActivity().trim().isEmpty()
			|| value.getMethod() == null || value.getSuccesses() < 0 || value.getFailures() < 0
			|| value.getSuccesses() > Long.MAX_VALUE - value.getFailures()
			|| (value.getMethod() == TrackingMethod.SUCCESS_ONLY && value.getFailures() != 0)
			|| (value.getMethod() == TrackingMethod.TIMED && value.getCycleTicks() < 1))
		{
			return null;
		}
		String id = value.getId() == null ? "" : value.getId().trim();
		if (id.isEmpty())
		{
			id = UUID.randomUUID().toString();
		}
		long startedAt = Math.max(0L, Math.min(now, value.getStartedAt()));
		long updatedAt = Math.max(startedAt, Math.min(now, value.getUpdatedAt()));
		return new AttemptSession(id, value.getActivity().trim(), normalizedSetup(value.getSetup()),
			value.getMethod(), startedAt, updatedAt, value.getSuccesses(), value.getFailures(),
			Math.max(0, value.getExcludedWindows()),
			value.getMethod() == TrackingMethod.TIMED ? value.getCycleTicks() : 0);
	}

	private static final class Profile
	{
		private final String activity;
		private final String setup;
		private final TrackingMethod method;
		private final int cycleTicks;

		private Profile(String activity, String setup, TrackingMethod method, int cycleTicks)
		{
			this.activity = activity;
			this.setup = setup;
			this.method = method;
			this.cycleTicks = cycleTicks;
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other) { return true; }
			if (!(other instanceof Profile)) { return false; }
			Profile profile = (Profile) other;
			return cycleTicks == profile.cycleTicks && activity.equals(profile.activity)
				&& setup.equals(profile.setup) && method == profile.method;
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(activity, setup, method, cycleTicks);
		}
	}
}

package com.attempttracker.core;

/**
 * A serializable session value. The engine returns copies so callers cannot alter
 * live counters. Timed attempts count completed active cycles after an explicit
 * action start; catches are successes and silent cycle deadlines are failures.
 */
public final class AttemptSession
{
	private static final double WILSON_Z = 1.959963984540054;

	private String id;
	private String activity;
	private String setup;
	private TrackingMethod method;
	private long startedAt;
	private long updatedAt;
	private long successes;
	private long failures;
	private int excludedWindows;
	private int cycleTicks;

	/** For JSON deserialization. Pass deserialized values through engine.restore(). */
	public AttemptSession()
	{
	}

	/** Constructs a persisted value; restore validates it before using its counters. */
	public AttemptSession(String id, String activity, String setup, TrackingMethod method,
		long startedAt, long updatedAt, long successes, long failures,
		int excludedWindows, int cycleTicks)
	{
		this.id = id;
		this.activity = activity;
		this.setup = setup;
		this.method = method;
		this.startedAt = startedAt;
		this.updatedAt = updatedAt;
		this.successes = successes;
		this.failures = failures;
		this.excludedWindows = excludedWindows;
		this.cycleTicks = cycleTicks;
	}

	public String getId() { return id; }
	public String getActivity() { return activity; }
	public String getSetup() { return setup; }
	public TrackingMethod getMethod() { return method; }
	public long getStartedAt() { return startedAt; }
	public long getUpdatedAt() { return updatedAt; }
	public long getSuccesses() { return successes; }
	public long getFailures() { return failures; }
	public int getExcludedWindows() { return excludedWindows; }
	public int getCycleTicks() { return cycleTicks; }

	public long getAttempts()
	{
		if (method == TrackingMethod.SUCCESS_ONLY)
		{
			return 0;
		}
		// Also safe on malformed deserialized values awaiting restore.
		if (successes < 0 || failures < 0)
		{
			return 0;
		}
		return successes > Long.MAX_VALUE - failures ? Long.MAX_VALUE : successes + failures;
	}

	public double getSuccessRate()
	{
		if (method == TrackingMethod.SUCCESS_ONLY || successes < 0 || failures < 0
			|| (successes == 0 && failures == 0))
		{
			return Double.NaN;
		}
		return successes / ((double) successes + failures);
	}

	public double getConfidenceLower()
	{
		return confidenceBound(false);
	}

	public double getConfidenceUpper()
	{
		return confidenceBound(true);
	}

	/** A two-sided 95% Wilson interval for the observed trial proportion. */
	private double confidenceBound(boolean upper)
	{
		double rate = getSuccessRate();
		if (Double.isNaN(rate))
		{
			return Double.NaN;
		}
		double n = (double) successes + failures;
		double zSquared = WILSON_Z * WILSON_Z;
		double denominator = 1.0 + zSquared / n;
		double center = (rate + zSquared / (2.0 * n)) / denominator;
		double margin = WILSON_Z * Math.sqrt(rate * (1.0 - rate) / n
			+ zSquared / (4.0 * n * n)) / denominator;
		return Math.max(0.0, Math.min(1.0, upper ? center + margin : center - margin));
	}

	public AttemptSession copy()
	{
		return new AttemptSession(id, activity, setup, method, startedAt, updatedAt,
			successes, failures, excludedWindows, cycleTicks);
	}

	boolean addCounts(long addedSuccesses, long addedFailures, long now)
	{
		if (addedSuccesses < 0 || addedFailures < 0 || successes < 0 || failures < 0
			|| successes > Long.MAX_VALUE - failures)
		{
			return false;
		}
		long remaining = Long.MAX_VALUE - successes - failures;
		if (addedSuccesses > remaining || addedFailures > remaining - addedSuccesses)
		{
			return false;
		}
		successes += addedSuccesses;
		failures += addedFailures;
		touch(now);
		return true;
	}

	/** Removes only bounded contributions from an invalidated timing run. */
	boolean removeCounts(long removedSuccesses, long removedFailures, long now)
	{
		if (removedSuccesses < 0 || removedFailures < 0
			|| removedSuccesses > successes || removedFailures > failures)
		{
			return false;
		}
		successes -= removedSuccesses;
		failures -= removedFailures;
		touch(now);
		return true;
	}

	void excludeWindow(long now)
	{
		if (excludedWindows < Integer.MAX_VALUE)
		{
			excludedWindows++;
		}
		touch(now);
	}

	void touch(long now)
	{
		updatedAt = Math.max(updatedAt, Math.max(startedAt, now));
	}
}

package com.attempttracker.core;

/** Whether outcomes are observed directly or failures are inferred from timing. */
public enum TrackingMethod
{
	OBSERVED,
	TIMED,
	/** Successful outcomes are visible, but no attempt denominator is established. */
	SUCCESS_ONLY
}

package com.attempttracker.core;

import java.util.ArrayList;
import java.util.List;
import java.util.HashMap;
import java.util.Map;
import java.util.function.LongSupplier;

/** Session totals and monotonic active clocks, independent of client tick numbering. */
public final class FishingSessions
{
	private final LongSupplier nanoClock;
	private final List<FishingSession> sessions = new ArrayList<>();
	private final VariableRollTracker variable = new VariableRollTracker();
	private Map<String, long[]> previous = new HashMap<>();
	private long lastNanos;
	private boolean logged, fishing, variableActive;
	private long runMinimum, runMaximum, runSuccesses;

	public FishingSessions() { this(System::nanoTime); }
	public FishingSessions(LongSupplier nanoClock) { this.nanoClock = nanoClock; lastNanos = nanoClock.getAsLong(); sessions.add(new FishingSession()); }
	public void restore(List<FishingSession> saved)
	{
		sessions.clear();
		if (saved != null)
		{
			for (FishingSession entry : saved)
			{
				if (entry != null && entry.id != null && entry.startedAt > 0 && entry.catches >= 0 && entry.measuredCatches >= 0
					&& entry.measuredCatches <= entry.catches && entry.minimumFailures >= 0 && entry.maximumFailures >= entry.minimumFailures
					&& entry.loggedMillis >= 0 && entry.fishingMillis >= 0 && entry.fishingMillis <= entry.loggedMillis && entry.fishingTicks >= 0)
				{
					sessions.add(entry.copy()); if (sessions.size() == 200) { break; }
				}
			}
		}
		if (sessions.isEmpty() || sessions.get(0).endedAt != 0) { sessions.add(0, new FishingSession()); }
		logged = fishing = variableActive = false; lastNanos = nanoClock.getAsLong();
	}
	public void baseline(List<AttemptSession> history)
	{
		previous.clear(); for (AttemptSession entry : history) { previous.put(entry.getId(), totals(entry)); }
	}
	public void importPrevious(List<AttemptSession> history)
	{
		for (AttemptSession entry : history)
		{
			if (entry.getActivity().startsWith("Fishing:") && entry.getMethod() == TrackingMethod.TIMED)
			{
				FishingSession current = current(); current.startedAt = entry.getStartedAt(); current.catches = current.measuredCatches = entry.getSuccesses();
				current.minimumFailures = current.maximumFailures = entry.getFailures(); break;
			}
		}
		baseline(history);
	}
	public void sync(List<AttemptSession> history)
	{
		long[] delta = new long[3]; Map<String, long[]> next = new HashMap<>();
		for (AttemptSession entry : history)
		{
			long[] total = totals(entry); long[] old = previous.getOrDefault(entry.getId(), new long[3]);
			for (int i = 0; i < 3; i++) { delta[i] += total[i] - old[i]; }
			next.put(entry.getId(), total);
		}
		FishingSession current = current();
		current.catches = Math.max(0, current.catches + delta[0]); current.measuredCatches = Math.max(0, current.measuredCatches + delta[1]);
		current.minimumFailures = Math.max(0, current.minimumFailures + delta[2]);
		current.maximumFailures = Math.max(current.minimumFailures, current.maximumFailures + delta[2]); previous = next;
	}
	private static long[] totals(AttemptSession entry)
	{
		long[] total = new long[3];
		if (!entry.getActivity().startsWith("Fishing:")) { return total; }
		total[0] = entry.getSuccesses();
		if (entry.getMethod() != TrackingMethod.SUCCESS_ONLY) { total[1] = entry.getSuccesses(); total[2] = entry.getFailures(); }
		return total;
	}
	public void advance(boolean nextLogged, boolean nextFishing)
	{
		long now = nanoClock.getAsLong(); long elapsed = Math.max(0, now - lastNanos);
		if (logged) { current().loggedMillis += elapsed / 1_000_000; }
		if (fishing) { current().fishingMillis += elapsed / 1_000_000; }
		lastNanos = now; logged = nextLogged; fishing = nextLogged && nextFishing;
	}
	public void fishingTick() { current().fishingTicks++; }
	public void reset()
	{
		advance(logged, false); stopVariable(); current().endedAt = System.currentTimeMillis();
		sessions.add(0, new FishingSession()); if (sessions.size() > 200) { sessions.remove(sessions.size() - 1); }
	}
	public void startVariable(int tick, int shortest, int longest)
	{
		stopVariable(); variable.start(tick, shortest, longest, shortest - 1, longest - 1);
		variableActive = true; runMinimum = runMaximum = runSuccesses = 0; current().variableTiming = true;
	}
	public boolean observeVariable(int tick, int catches)
	{
		if (!variableActive) { return false; }
		if (!variable.observe(tick, catches))
		{
			current().minimumFailures -= runMinimum; current().maximumFailures -= runMaximum; current().measuredCatches -= runSuccesses;
			stopVariable(); return false;
		}
		current().minimumFailures += variable.getMinimumFailures() - runMinimum;
		current().maximumFailures += variable.getMaximumFailures() - runMaximum;
		current().measuredCatches += variable.getSuccesses() - runSuccesses;
		runMinimum = variable.getMinimumFailures(); runMaximum = variable.getMaximumFailures(); runSuccesses = variable.getSuccesses();
		return true;
	}
	public boolean isVariableActive() { return variableActive; }
	public void stopVariable() { variableActive = false; runMinimum = runMaximum = runSuccesses = 0; }
	public FishingSession current() { return sessions.get(0); }
	public List<FishingSession> snapshots()
	{
		List<FishingSession> copy = new ArrayList<>(); for (FishingSession entry : sessions) { copy.add(entry.copy()); } return copy;
	}
}

package com.attempttracker.core;

import java.util.HashMap;
import java.util.Map;

/** All schedules consistent with variable roll intervals and observed catches. */
public final class VariableRollTracker
{
	private Map<Long, long[]> schedules = new HashMap<>();
	private int shortest;
	private int longest;
	private int lastTick;
	private boolean observed;
	private long successes;
	private long minimum;
	private long maximum;

	public void start(int tick, int shortest, int longest, int firstShortest, int firstLongest)
	{
		if (shortest < 1 || longest < shortest || longest > 100 || firstShortest < 1 || firstLongest < firstShortest || firstLongest > 100)
		{
			throw new IllegalArgumentException("Invalid roll intervals");
		}
		this.shortest = shortest; this.longest = longest; lastTick = tick; observed = false;
		successes = minimum = maximum = 0; schedules.clear();
		for (int delay = firstShortest; delay <= firstLongest; delay++) { schedules.put((long) tick + delay, new long[]{0, 0}); }
	}

	/** False rejects the current run; never manufactures a precise random interval. */
	public boolean observe(int tick, int catches)
	{
		if (schedules.isEmpty() || catches < 0 || catches > 1 || (observed ? (long) tick - lastTick != 1 : tick != lastTick)) { return false; }
		Map<Long, long[]> next = new HashMap<>();
		for (Map.Entry<Long, long[]> entry : schedules.entrySet())
		{
			long due = entry.getKey(); long[] failures = entry.getValue();
			if (due > tick)
			{
				if (catches == 0) { merge(next, due, failures[0], failures[1]); }
			}
			else if (due == tick)
			{
				long failed = catches == 0 ? 1 : 0;
				for (int delay = shortest; delay <= longest; delay++) { merge(next, (long) tick + delay, failures[0] + failed, failures[1] + failed); }
			}
		}
		if (next.isEmpty()) { return false; }
		schedules = next; lastTick = tick; observed = true; successes += catches;
		minimum = Long.MAX_VALUE; maximum = 0;
		for (long[] failures : schedules.values()) { minimum = Math.min(minimum, failures[0]); maximum = Math.max(maximum, failures[1]); }
		return true;
	}

	private static void merge(Map<Long, long[]> schedules, long due, long min, long max)
	{
		long[] existing = schedules.get(due);
		if (existing == null) { schedules.put(due, new long[]{min, max}); }
		else { existing[0] = Math.min(existing[0], min); existing[1] = Math.max(existing[1], max); }
	}
	public long getMinimumFailures() { return minimum; }
	public long getMaximumFailures() { return maximum; }
	public long getSuccesses() { return successes; }
}

package com.attempttracker.activity;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Conservative, client-independent parser for action-result game messages.
 * The caller must filter to RuneLite SPAM/GAMEMESSAGE events; player chat is not
 * evidence that an action occurred. Each parsed message represents one result,
 * never the number of items produced by that result.
 *
 * <p>Message families and fixtures are checked against these primary sources:</p>
 * <ul>
 * <li>runelite/runelite: FishingPlugin and FishingPluginTest</li>
 * <li>runelite/runelite: CookingPlugin and CookingPluginTest</li>
 * <li>runelite/runelite: WoodcuttingPlugin and WoodcuttingPluginTest</li>
 * <li>Skretzo/runelite-plugins, chat-success-rates branch: MiningRock,
 * Pickpocketing and ChatSuccessRatesAction</li>
 * <li>pajlads/runelite-pickpocket-helper: utility/MessagePattern</li>
 * </ul>
 *
 * <p>Starts, bonus-item notifications, inventory-full notices, cooking
 * conversions and unsupported item names deliberately return empty.</p>
 */
public final class ActivityMessages
{
	private static final Pattern FORMATTING = Pattern.compile("<[^>]*>|@[a-z0-9_]+@", Pattern.CASE_INSENSITIVE);
	private static final Pattern WHITESPACE = Pattern.compile("\\s+");
	// Live shark catches use "!"; RuneLite's fishing fixtures also include ".".
	private static final Pattern FISHING = Pattern.compile("you catch (?:a|an|some) ([a-z][a-z -]*)[.!]");
	// RuneLite's official fixture is "You catch 15 Karambwanji.". A single
	// message is one catch result, even when that result awards many bait fish.
	private static final Pattern KARAMBWANJI = Pattern.compile("you catch [1-9][0-9]* karambwanji[.!]");
	private static final Pattern COOKING_SUCCESS = Pattern.compile(
		"you (?:(?:successfully (?:cook|bake|fry))|(?:manage to cook)|cook|roast) "
			+ "(?:a|an|some|the) ([a-z][a-z -]*)\\.");
	private static final Pattern COOKING_FAILURE = Pattern.compile(
		"you accidentally burn (?:a|an|some|the) ([a-z][a-z -]*)\\.");
	private static final Pattern PICKPOCKET_SUCCESS = Pattern.compile(
		"you pick (?:the )?[a-z][a-z '-]* pocket\\.");
	private static final Pattern PICKPOCKET_FAILURE = Pattern.compile(
		"you fail to pick (?:the )?[a-z][a-z '-]* pocket\\.");
	private static final Pattern MINING = Pattern.compile("you manage to mine some ([a-z][a-z ]*)\\.");
	private static final Pattern WOODCUTTING = Pattern.compile("you get (?:some|an) ([a-z][a-z ]*)\\.");

	private static final Map<String, String> FISH = fishNames();
	private static final Map<String, String> FOOD = foodNames();
	private static final Map<String, String> ORE = oreNames();
	private static final Map<String, String> WOOD = woodNames();

	private ActivityMessages()
	{
	}

	public static Optional<ActivityOutcome> parse(String message)
	{
		if (message == null || message.isEmpty())
		{
			return Optional.empty();
		}
		String text = normalize(message);
		Optional<ActivityOutcome> result = named(FISHING, text, FISH, "Fishing", "FISHING", true, true);
		if (result.isPresent())
		{
			return result;
		}
		if (KARAMBWANJI.matcher(text).matches())
		{
			return outcome("Fishing: Karambwanji", "FISHING", true, true);
		}
		result = named(COOKING_SUCCESS, text, FOOD, "Cooking", "COOKING", true, false);
		if (result.isPresent())
		{
			return result;
		}
		// Explicit special messages used by RuneLite's core cooking plugin.
		if (text.equals("you cook the karambwan. it looks delicious."))
		{
			return outcome("Cooking: Karambwan", "COOKING", true, false);
		}
		if (text.equals("you burn the mushroom in the fire."))
		{
			return outcome("Cooking: Mushroom", "COOKING", false, false);
		}
		result = named(COOKING_FAILURE, text, FOOD, "Cooking", "COOKING", false, false);
		if (result.isPresent())
		{
			return result;
		}
		if (PICKPOCKET_SUCCESS.matcher(text).matches())
		{
			return outcome("Pickpocketing", "THIEVING", true, false);
		}
		if (PICKPOCKET_FAILURE.matcher(text).matches())
		{
			return outcome("Pickpocketing", "THIEVING", false, false);
		}
		result = named(MINING, text, ORE, "Mining", "MINING", true, true);
		if (result.isPresent())
		{
			return result;
		}
		return named(WOODCUTTING, text, WOOD, "Woodcutting", "WOODCUTTING", true, true);
	}

	private static Optional<ActivityOutcome> named(Pattern pattern, String message,
		Map<String, String> names, String activity, String skill, boolean success, boolean timed)
	{
		Matcher matcher = pattern.matcher(message);
		if (!matcher.matches())
		{
			return Optional.empty();
		}
		String name = names.get(matcher.group(1));
		return name == null ? Optional.empty() : outcome(activity + ": " + name, skill, success, timed);
	}

	private static Optional<ActivityOutcome> outcome(String activity, String skill, boolean success, boolean timed)
	{
		return Optional.of(new ActivityOutcome(activity, skill, success, timed));
	}

	private static String normalize(String message)
	{
		return WHITESPACE.matcher(FORMATTING.matcher(message).replaceAll("")
			.replace('\u00a0', ' ').replace('\u2019', '\''))
			.replaceAll(" ").trim().toLowerCase(Locale.ROOT);
	}

	private static Map<String, String> fishNames()
	{
		Map<String, String> names = new LinkedHashMap<>();
		add(names, "Shrimp", "shrimp", "shrimps");
		add(names, "Anchovies", "anchovies");
		add(names, "Sardine", "sardine", "sardines");
