	private static Map<String, String> foodNames()
	{
		Map<String, String> names = new LinkedHashMap<>(FISH);
		// These gatherable fish do not use the ordinary cook/burn mechanic.
		for (String unsupported : new String[]{"karambwanji", "sacred eel", "infernal eel",
			"leaping trout", "leaping salmon", "leaping sturgeon", "minnow", "minnows",
			"guppy", "guppies", "cavefish", "tetra", "catfish"})
		{
			names.remove(unsupported);
		}
		add(names, "Mushroom", "mushroom", "mushrooms");
		add(names, "Meat", "meat", "piece of meat");
		add(names, "Chicken", "chicken");
		add(names, "Bread", "bread");
		// Burn messages can identify only "the pie", even when a successful
		// bake names the flavor. Keep both outcomes in one explicitly aggregate
		// profile; counting named successes without their generic failures
		// would systematically inflate the measured success rate.
		add(names, "Pie", "pie", "garden pie", "tasty garden pie", "apple pie",
			"redberry pie", "meat pie", "fish pie", "admiral pie", "wild pie", "summer pie");
		return Collections.unmodifiableMap(names);
	}

	private static Map<String, String> oreNames()
	{
		Map<String, String> names = new LinkedHashMap<>();
		for (String ore : new String[]{"copper", "tin", "iron", "silver", "gold", "mithril",
			"adamantite", "runite", "blurite"})
		{
			String label = Character.toUpperCase(ore.charAt(0)) + ore.substring(1) + " ore";
			add(names, label, ore, ore + " ore");
		}
		add(names, "Coal", "coal");
		add(names, "Clay", "clay");
		return Collections.unmodifiableMap(names);
	}

	private static Map<String, String> woodNames()
	{
		Map<String, String> names = new LinkedHashMap<>();
		add(names, "Logs", "logs", "log");
		for (String wood : new String[]{"oak", "willow", "teak", "maple", "mahogany", "yew",
			"magic", "redwood", "arctic", "pine", "juniper"})
		{
			String label = Character.toUpperCase(wood.charAt(0)) + wood.substring(1) + " logs";
			add(names, label, wood + " logs", wood + " log");
		}
		add(names, "Arctic logs", "arctic logs", "arctic log");
		add(names, "Mushrooms", "mushrooms");
		return Collections.unmodifiableMap(names);
	}

	private static void add(Map<String, String> names, String label, String... aliases)
	{
		for (String alias : aliases)
		{
			names.put(alias, label);
		}
	}
}

package com.attempttracker.activity;

import java.util.Locale;
import java.util.Optional;
import java.util.regex.Pattern;
import net.runelite.api.Skill;

/**
 * Exact gathering-start messages that can establish a fixed-cycle schedule.
 * A start is not itself a successful or failed result. The caller must filter
 * game-message channels and validate the target, animation and timing mode.
 */
public final class ActivityStarts
{
	private static final Pattern FORMATTING = Pattern.compile("<[^>]*>|@[a-z0-9_]+@", Pattern.CASE_INSENSITIVE);
	private static final Pattern WHITESPACE = Pattern.compile("\\s+");

	private ActivityStarts() { }

	public static Optional<Skill> parseStart(String message)
	{
		String clean = normalize(message);
		if (matches(clean, "you start harpooning fish") || matches(clean, "you cast out your line"))
		{
			return Optional.of(Skill.FISHING);
		}
		if (matches(clean, "you swing your pick at the rock"))
		{
			return Optional.of(Skill.MINING);
		}
		if (matches(clean, "you swing your axe at the tree"))
		{
			return Optional.of(Skill.WOODCUTTING);
		}
		return Optional.empty();
	}

	public static boolean isHarpooning(String message)
	{
		return matches(normalize(message), "you start harpooning fish");
	}

	private static boolean matches(String message, String body)
	{
		return message.equals(body) || message.equals(body + ".") || message.equals(body + "!") || message.equals(body + "...");
	}

	private static String normalize(String message)
	{
		return WHITESPACE.matcher(FORMATTING.matcher(message == null ? "" : message).replaceAll("")
			.replace('\u00a0', ' ').replace('\u2019', '\''))
			.replaceAll(" ").trim().toLowerCase(Locale.ROOT);
	}
}

package com.attempttracker.activity;

import java.util.Objects;

/** A single action outcome described explicitly by a game message. */
public final class ActivityOutcome
{

	private final String activity;
	private final String skillName;
	private final boolean success;
	private final boolean timed;

	ActivityOutcome(String activity, String skillName, boolean success, boolean timed)
	{
		this.activity = Objects.requireNonNull(activity, "activity");
		this.skillName = Objects.requireNonNull(skillName, "skillName");
		this.success = success;
		this.timed = timed;
	}

	public String getActivity()
	{
		return activity;
	}

	/** The spelling of the corresponding RuneLite Skill enum constant. */
	public String getSkillName()
	{
		return skillName;
	}

	public boolean isSuccess()
	{
		return success;
	}

	/**
	 * Whether an adapter must identify timed rolls to measure silent failures.
	 * This flag does not itself assert that a failure or a particular roll happened.
	 */
	public boolean isTimed()
	{
		return timed;
	}
}

package com.attempttracker;

import java.util.Locale;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.NpcID;
import net.runelite.client.game.FishingSpot;
import net.runelite.client.util.Text;

/** Actual fishing activity, independent of whether its roll schedule is known. */
final class FishingActivityTracker
{
	private NPC spot;
	private WorldPoint spotPosition;
	private WorldPoint playerPosition;
	private boolean active;
	private int startedTick = -1;

	static boolean isFishingOption(String option)
	{
		if (option == null) { return false; }
		switch (Text.removeTags(option).trim().toLowerCase(Locale.ROOT))
		{
			case "fish": case "net": case "small net": case "big net": case "large net":
			case "bait": case "lure": case "harpoon": case "cage": case "use-rod":
				return true;
			default: return false;
		}
	}
	static boolean isFishingSpot(NPC npc)
	{
		if (npc == null) { return false; }
		if (npc.getId() == NpcID._0_40_34_MEMBERFISH || FishingSpot.findSpot(npc.getId()) != null) { return true; }
		String name = npc.getName();
		if (name == null || !Text.removeTags(name).toLowerCase(Locale.ROOT).contains("fishing spot")) { return false; }
		NPCComposition definition = npc.getTransformedComposition();
		if (definition == null || definition.getActions() == null) { return false; }
		for (String action : definition.getActions()) { if (isFishingOption(action)) { return true; } }
		return false;
	}
	void select(NPC npc)
	{
		if (!isFishingSpot(npc)) { stop(); return; }
		if (spot == npc && spotPosition != null && spotPosition.equals(npc.getWorldLocation())) { return; }
		stop(); spot = npc; spotPosition = npc.getWorldLocation();
	}
	boolean update(Player player, int tick)
	{
		if (spot == null || spotPosition == null || player == null) { stop(); return false; }
		Actor interaction = player.getInteracting();
		WorldPoint position = player.getWorldLocation();
		if (!spotPosition.equals(spot.getWorldLocation()) || player.getWorldView() != spot.getWorldView()
			|| position == null || position.getPlane() != spotPosition.getPlane()
			|| (interaction != null && interaction != spot)
			|| (active && playerPosition != null && !playerPosition.equals(position))) { stop(); return false; }
		boolean moving = playerPosition != null && !playerPosition.equals(position);
		playerPosition = position;
		boolean fishing = !moving && AnimationCatalog.skillFor(player.getAnimation()) == Skill.FISHING;
		// Aerial fishing intentionally targets remote pools. Other spots require adjacency.
		if (FishingSpot.findSpot(spot.getId()) != FishingSpot.COMMON_TENCH && position.distanceTo(spotPosition) > 1) { fishing = false; }
		if (!fishing) { if (active) { stop(); } return false; }
		if (!active) { startedTick = tick; active = true; }
		return true;
	}
	boolean isActive() { return active; }
	int getStartedTick() { return startedTick; }
	boolean targets(NPC npc) { return spot == npc; }
	void stop() { spot = null; spotPosition = null; playerPosition = null; active = false; startedTick = -1; }
}

